<!doctype html>
<html lang="en">
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta http-equiv="refresh" content="10"><title>Token {{ $queueEntry->token_number }}</title><style>body{font-family:Arial,sans-serif;background:#f8fafc;margin:0;padding:32px;color:#17202a}.card{max-width:420px;margin:0 auto;background:#fff;border:1px solid #e2e8f0;border-radius:16px;padding:28px;text-align:center;box-shadow:0 8px 24px #0f172a12}.token{font-size:72px;font-weight:700;margin:16px 0}.status{display:inline-block;border-radius:999px;background:#dcfce7;color:#166534;padding:8px 16px;font-weight:600}.muted{color:#64748b;font-size:14px}.refresh{border:1px solid #cbd5e1;border-radius:8px;background:#fff;color:#334155;padding:8px 12px;cursor:pointer}</style></head>
<body><main class="card"><p class="muted">Your queue token</p><div class="token">{{ $queueEntry->token_number }}</div><h1>{{ $queueEntry->doctor->name }}</h1><p class="muted">{{ $queueEntry->queue_date->format('d M Y') }}</p><p class="status">{{ ucfirst(str_replace('_', ' ', $queueEntry->status)) }}</p><button class="refresh" type="button" onclick="window.location.reload()">Refresh now</button><p class="muted">Last checked <time id="last-checked"></time></p><p class="muted">This page shows queue status only. No patient or medical information is displayed.</p></main><script>document.getElementById('last-checked').textContent=new Date().toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'});</script></body>
</html>
